/* "Who's telling me this?" — dossiers on the sources the Lab relies on: who pays them, who runs them, what they gain, who criticizes them.
   Lab.source() is patched so every source line can open the matching dossiers. */
(function () {
  const h = Lab.h;
  // [id, name, match regex, type, who runs & pays, what they want / gain, what they're good for, criticisms (and who makes them), how to read them]
  const S = [
    ['gapminder', 'Gapminder Foundation', /gapminder/i, 'Nonprofit data project', 'Swedish nonprofit founded in 2005 by Hans Rosling, Ola Rosling and Anna Rosling Rönnlund. Funded by grants from foundations and public bodies; publishes its data free.', 'Its mission is to fight “misconceptions” with a “fact-based worldview”. Its founders’ book Factfulness (2018) argues the world is better than people think, so it has a stake in a progress story.', 'Long country series (since 1800) for life expectancy, child mortality, income and poverty, stitched together from the UN, World Bank, historians and others; clear documentation of each series.', 'Before about 1950 many numbers are modeled or interpolated, not measured. Critics such as anthropologist Jason Hickel argue the progress framing understates suffering and depends on low poverty lines.', 'Excellent for long-run trends; treat early numbers as estimates and check the documentation for how each series was built.'],
    ['owid', 'Our World in Data', /our world in data|owid/i, 'Nonprofit data publisher', 'Run by the Global Change Data Lab (UK charity) with researchers at the University of Oxford. Funded by grants and donations; donors have included the Bill & Melinda Gates Foundation and other philanthropies, listed on its site.', 'Wants to make research on big problems understandable. Its founder Max Roser emphasizes that progress is possible, so it, too, can lean toward an improvement narrative.', 'Republishes data from the UN, World Bank, academic studies and others with charts, sources and open code.', 'Same progress-framing critique as Gapminder (Hickel and others). It compiles rather than collects, so its numbers are only as good as the original sources.', 'Click through to the original source every time; read the “sources and processing” notes.'],
    ['worldbank', 'World Bank', /world bank|\bwdi\b/i, 'International lender (governments)', 'Owned by 189 member governments; votes weighted by money contributed. The US is the largest shareholder (about 16%) and can veto major changes; its president has always been an American.', 'Lends to governments and promotes economic growth through markets, trade and investment; its loans have often come with policy conditions. It has an interest in showing development programs work.', 'Global poverty estimates, household survey data, World Development Indicators.', 'Critics on the left (and many in the Global South) blame its 1980s–90s structural adjustment conditions for cuts to health and education; critics on the right call it bureaucratic. Its poverty line (raised from $2.15 to $3.00 a day in 2025 with new price data) is called far too low by Hickel and others.', 'Good for standardized cross-country data; check which poverty line and which price year are used.'],
    ['imf', 'International Monetary Fund (IMF)', /\bIMF\b|International Monetary Fund/, 'International lender (governments)', 'Owned by 190 member governments; voting by quota. The US holds about 16.5% and can block major decisions (85% needed); its head has always been a European.', 'Lends to countries in crisis, usually with conditions (spending cuts, privatization, tax changes). Its forecasts and reports shape markets and policy.', 'GDP, debt, inflation and balance-of-payments data; the World Economic Outlook.', 'Critics (Stiglitz, many governments) argue its austerity conditions deepened crises in Asia (1997), Argentina and Greece; the IMF itself later admitted it underestimated how much austerity hurt growth (2013).', 'Reliable for standardized macro data; treat its policy advice as one school of thought.'],
    ['un', 'United Nations agencies (UN DESA, UNICEF, UNDP, FAO)', /UN DESA|UNICEF|UNDP|\bFAO\b|United Nations|\bUN\b|UN-Habitat|UNHCR/, 'Intergovernmental', 'Funded by member states (required dues plus voluntary donations, often earmarked by big donors such as the US, Germany, the EU and foundations). Governed by member governments, including authoritarian ones.', 'Agencies need to show problems are serious (to raise funds) and progress is possible (to show their programs work). They depend on governments for data and access, so they rarely accuse powerful members directly.', 'The most complete global statistics on population, food, children, refugees and development.', 'Data often come from governments themselves, which can manipulate them; politically sensitive findings get softened. Critics on the right say the UN is biased against Israel or the West; critics elsewhere say Western donors set its agenda.', 'Ask whether a figure was measured independently or reported by the government in question.'],
    ['who', 'World Health Organization (WHO)', /\bWHO\b|World Health Organization/, 'Intergovernmental (health)', 'UN agency governed by member states. Only about a fifth of its budget is required dues; the rest is voluntary and earmarked. The Gates Foundation has been one of its largest funders; the US announced its withdrawal in 2025.', 'Coordinates global health; needs cooperation from governments, including the ones it may need to criticize.', 'Global health statistics, disease surveillance, treatment guidelines.', 'Criticized for praising China’s early COVID-19 response (2020) and for donor-driven priorities; critics of the Gates influence say private money shapes public health agendas.', 'Strong on technical health data; read political statements with care.'],
    ['ilo', 'International Labour Organization (ILO)', /\bILO\b|International Labour/, 'Intergovernmental (labor)', 'UN agency with a unique structure: governments, employers’ groups and trade unions each have votes.', 'Promotes labor standards; co-produces global estimates of forced labor and modern slavery with Walk Free and the IOM.', 'Labor statistics (working hours, employment, child and forced labor).', 'Its compromises among governments, employers and unions can soften findings; forced-labor estimates rely on surveys that cannot reach some countries.', 'Good for definitions and labor law; check the methods notes on survey coverage.'],
    ['walkfree', 'Walk Free Foundation (Global Slavery Index)', /walk free|global slavery index/i, 'Private foundation', 'Founded in 2012 by Australian iron-ore billionaire Andrew Forrest and Nicola Forrest; part of their Minderoo Foundation.', 'Advocates for ending modern slavery and for laws requiring companies to report on supply chains. Large numbers help its campaign.', 'Co-produces (with the ILO and IOM) the global estimate of about 50 million people in modern slavery (2021); country rankings.', 'Researchers including Anne Gallagher (2017) criticized the index’s country estimates as extrapolated from limited surveys. Forrest’s mining company Fortescue has had long legal disputes with Aboriginal groups over land and royalties, which critics cite as a contradiction.', 'Use the global ILO/Walk Free/IOM estimate rather than individual country rankings, and note what is included (forced marriage counts as slavery).'],
    ['freedomhouse', 'Freedom House', /freedom house/i, 'US nonprofit / think tank', 'US nonprofit founded in 1941. For years most of its budget came from US government grants (State Department, USAID); 2025 US funding cuts forced deep layoffs.', 'Promotes democracy and human rights worldwide, a goal aligned with US foreign policy.', 'Annual ratings of political rights and civil liberties for every country since 1972.', 'Critics (including governments it rates poorly and some scholars) say it is soft on US allies and reflects US priorities; defenders note it has steadily downgraded the US itself.', 'Compare with V-Dem (different method and funders); read the country narratives, not only the score.'],
    ['vdem', 'V-Dem Institute', /v-?dem/i, 'University research institute', 'Based at the University of Gothenburg, Sweden; funded by Swedish and European research councils, governments and foundations.', 'Academic project measuring democracy in many dimensions; it publicizes democratic backsliding.', 'Very detailed democracy data back to 1789, coded by over 3,500 country experts.', 'Expert judgments can share a liberal Western idea of democracy; India’s government rejected its “electoral autocracy” rating (2021); some political scientists argue it overstates recent backsliding.', 'Look at the separate components (elections, courts, media) rather than one summary score.'],
    ['fraser', 'Fraser Institute', /fraser institute|economic freedom of the world|\befw\b/i, 'Think tank (free-market)', 'Canadian free-market think tank funded by private foundations, companies and individuals, historically including foundations linked to the Koch family.', 'Promotes lower taxes, less regulation and free trade; its Economic Freedom index is designed around those values.', 'The Economic Freedom of the World index.', 'Critics say the index builds its conclusions into its definitions (lower taxes = more freedom) and that correlation with income does not show causation.', 'Useful to see how free-market economists measure freedom; compare with outcomes like health and inequality.'],
    ['heritage', 'Heritage Foundation', /heritage foundation|project 2025/i, 'Think tank (conservative)', 'US conservative think tank funded by individual donors and foundations.', 'Advances conservative policy; drafted Project 2025, a plan for a conservative administration.', 'Policy proposals and the Index of Economic Freedom.', 'Critics say its research serves predetermined political goals; supporters see it as a counterweight to liberal academia.', 'Read as advocacy: check its numbers against neutral sources.'],
    ['brookings', 'Brookings Institution', /brookings/i, 'Think tank (center / center-left)', 'Washington think tank funded by foundations, corporations, individuals and some foreign governments (a 2014 New York Times investigation highlighted large gifts from Qatar).', 'Influence on policy; many staff move between Brookings and Democratic (and some Republican) administrations.', 'Policy research on economics, governance and foreign policy.', 'Critics on the right call it liberal; critics on the left call it a corporate establishment voice; foreign funding raised conflict-of-interest questions.', 'Check who funded a specific report (Brookings lists donors).'],
    ['cato', 'Cato Institute', /\bCato\b/, 'Think tank (libertarian)', 'Libertarian think tank co-founded in 1977 by Charles Koch, funded by individual and foundation donors.', 'Promotes free markets, civil liberties and a non-interventionist foreign policy.', 'Research on regulation, immigration, criminal justice and trade.', 'Critics say its economic research serves wealthy donors’ interests; it often disagrees with both parties.', 'Read as advocacy from a clear philosophy; its data appendices are usually transparent.'],
    ['cap', 'Center for American Progress', /center for american progress/i, 'Think tank (progressive)', 'Progressive think tank founded in 2003 by John Podesta; funded by foundations, companies and individuals; close to Democratic administrations.', 'Advances progressive policy and Democratic priorities.', 'Policy research on health, economy, climate.', 'Critics say it is a partisan operation and that corporate donors influenced some work.', 'Read as advocacy; compare with conservative and neutral sources.'],
    ['pew', 'Pew Research Center', /\bPew\b/, 'Nonpartisan research', 'Funded mainly by The Pew Charitable Trusts (endowment from the Sun Oil family fortune). Takes no policy positions.', 'Its reputation depends on being seen as neutral.', 'Large, transparent surveys on politics, religion, media and demography in the US and worldwide.', 'Survey wording and sampling choices always shape results; some conservatives see a liberal tilt in topics and framing.', 'Very reliable for “what people say”; read the exact question wording.'],
    ['gallup', 'Gallup', /gallup/i, 'Private company (polling & consulting)', 'Private, for-profit company that sells consulting and survey services to companies and governments.', 'Commercial: its World Poll and well-being data are also products.', 'The World Poll used for life satisfaction and social support around the world.', 'Commercial data are not fully open; polling in authoritarian countries may make people afraid to answer honestly.', 'Good for comparing attitudes; remember that “life satisfaction” is a rating people give, shaped by culture.'],
    ['whr', 'World Happiness Report', /World Happiness|\bWHR\b/, 'Academic publication', 'Published by the UN Sustainable Development Solutions Network and the Wellbeing Research Centre at Oxford, using Gallup World Poll data.', 'Promotes measuring well-being instead of only GDP.', 'National life-satisfaction (Cantril ladder) scores since 2005.', 'Critics argue the ladder question measures how people rate their lives against wealth and status, not happiness or feelings, which favors rich, stable countries.', 'Combine with mood, mental health and social measures.'],
    ['cbo', 'Congressional Budget Office (CBO)', /\bCBO\b|Congressional Budget Office/, 'US government (Congress)', 'Nonpartisan agency of the US Congress, funded by Congress.', 'Its credibility depends on staying nonpartisan; it is often attacked by whichever party dislikes its estimate.', 'Federal budget data and cost estimates of legislation.', 'Its models must make assumptions about behavior; both parties have accused it of bias.', 'The best single source on US budget numbers; forecasts are uncertain.'],
    ['bls', 'US Bureau of Labor Statistics (BLS)', /\bBLS\b|Bureau of Labor Statistics|Consumer Price Index|CPI-U/, 'US government statistics', 'Statistical agency of the US Labor Department.', 'Official numbers on jobs, wages and prices, which move markets and elections.', 'Inflation (CPI), unemployment, wages.', 'Political pressure is real: in August 2025 President Trump fired the BLS commissioner after weak job numbers and revisions, raising concerns about independence. Definitions matter (the official unemployment rate excludes discouraged workers).', 'Compare several measures (e.g. U-3 vs U-6 unemployment) and watch for revisions.'],
    ['eia', 'US Energy Information Administration (EIA)', /\bEIA\b|Energy Information Administration/, 'US government statistics', 'Statistical agency of the US Department of Energy.', 'Provides official energy data; no policy role by law.', 'Oil, gas and electricity statistics, chokepoint flows.', 'Generally trusted; estimates for countries with secretive oil sectors are uncertain.', 'Reliable; check the date of estimates.'],
    ['opensecrets', 'OpenSecrets', /opensecrets|center for responsive politics/i, 'Nonprofit watchdog', 'Nonpartisan nonprofit funded by foundations and individual donors.', 'Wants transparency about money in US politics.', 'Lobbying and campaign finance data compiled from official filings.', 'Only shows disclosed spending; “dark money” and unregistered influence are invisible, so true totals are higher.', 'Treat its totals as a minimum.'],
    ['wikipedia', 'Wikipedia & Wikimedia Commons', /Wikipedia|Wikimedia/, 'Volunteer encyclopedia', 'Written by volunteers; the Wikimedia Foundation is funded mostly by small donations.', 'Aims for a neutral point of view backed by citations.', 'Quick overviews, links to sources, free images.', 'Uneven quality, edit wars and systemic bias (more coverage of Western topics, mostly male editors); co-founder Larry Sanger argues it leans left; governments and companies have been caught editing pages.', 'Use it to find sources, then read the sources.'],
    ['gutenberg', 'Project Gutenberg & Internet Archive', /gutenberg|internet archive/i, 'Nonprofit digital libraries', 'Volunteer and donor-funded nonprofits.', 'Free access to public-domain books.', 'Original texts of old books and documents.', 'The books themselves carry their era’s biases (racist and colonial views are common in older works); the Internet Archive has lost copyright lawsuits over modern books.', 'Primary sources: read them as evidence of what people thought then.'],
    ['nasa', 'NASA', /\bNASA\b/, 'US government agency', 'US federal space agency funded by Congress.', 'Science and exploration; needs public and congressional support.', 'Images and data about space and Earth.', 'Scientific data are widely trusted; budget politics shape which missions happen.', 'Reliable for science data.'],
    ['sipri', 'SIPRI', /sipri/i, 'Independent research institute', 'Stockholm International Peace Research Institute, funded mainly by the Swedish government plus grants.', 'Peace research and arms control.', 'Military spending, arms transfers, nuclear arsenals.', 'Some countries (China, Russia) hide military spending, so its figures are estimates.', 'The standard source for military spending; check whether figures are estimates.'],
    ['ucdp', 'Uppsala Conflict Data Program (UCDP)', /\bucdp\b|uppsala/i, 'University research', 'Uppsala University, Sweden; funded by research grants and the Swedish government.', 'Academic conflict research.', 'Deaths in armed conflicts since 1946.', 'Counts only well-documented deaths, so it undercounts; other projects (e.g. ACLED) use different rules.', 'Treat as a conservative minimum.'],
    ['cow', 'Correlates of War', /[Cc]orrelates of [Ww]ar|\bCOW\b/, 'University research', 'Long-running academic project (US universities) since 1963.', 'Academic study of war.', 'Wars, alliances and national capabilities since 1816.', 'Thresholds (e.g. 1,000 battle deaths) and state-centric definitions leave out many colonial and irregular wars.', 'Useful for big-picture comparisons.'],
    ['maddison', 'Maddison Project', /maddison/i, 'University research', 'University of Groningen, continuing the work of economic historian Angus Maddison.', 'Academic reconstruction of historical GDP.', 'GDP per person back centuries.', 'Pre-1900 figures are educated guesses built on very thin evidence; GDP itself ignores distribution and well-being.', 'Never treat early numbers as precise.'],
    ['slavevoyages', 'Trans-Atlantic Slave Trade Database (SlaveVoyages)', /slave trade database|slavevoyages/i, 'Academic database', 'Academic consortium (originally at Emory University), funded by research grants such as the US National Endowment for the Humanities.', 'Document the slave trade voyage by voyage.', 'About 36,000 voyages; estimates of about 12.5 million people embarked and 10.7 million who survived the crossing.', 'Records are incomplete, so totals are modeled; the Indian Ocean and trans-Saharan trades are not covered.', 'The best evidence for the Atlantic trade.'],
    ['hrw', 'Human Rights Watch', /Human Rights Watch|\bHRW\b/, 'Human rights NGO', 'Funded by private donors and foundations (George Soros’s Open Society Foundations pledged $100 million in 2010); refuses government money.', 'Exposes abuses to pressure governments.', 'Detailed field investigations of abuses worldwide.', 'Criticized by governments it targets (Israel, China, Russia, Gulf states and others) and by some on the left for focusing on enemies of the West; it returned a 2012 gift from a Saudi businessman after 2020 criticism.', 'Strong on documentation; check whether casualty figures are confirmed by others.'],
    ['amnesty', 'Amnesty International', /amnesty/i, 'Human rights NGO', 'Membership organization funded mostly by individual supporters; avoids government funding for research.', 'Campaigns for prisoners of conscience and human rights.', 'Reports on torture, political prisoners and war crimes.', 'Every government it criticizes calls it biased; a 2022 report on Ukrainian military tactics drew sharp criticism and an internal review.', 'Valuable testimony; cross-check numbers.'],
    ['aclu', 'ACLU', /\bACLU\b/, 'Advocacy nonprofit (civil liberties)', 'Membership- and donor-funded US civil liberties organization.', 'Litigates and advocates for civil liberties; on prisons it advocates for reform.', 'Reports such as “Captive Labor” (2022) on US prison labor.', 'An advocacy group: it chooses topics to support its legal campaigns; conservatives see a liberal tilt.', 'Check its figures against government data (e.g. the Bureau of Justice Statistics).'],
    ['ihme', 'IHME (Global Burden of Disease)', /IHME|Global Burden of Disease|\bGBD\b/, 'University research', 'Institute at the University of Washington founded in 2007 with large grants from the Gates Foundation.', 'Produces complete global health estimates.', 'Causes of death and disease for every country.', 'Where data are missing it fills gaps with models, sometimes disagreeing sharply with WHO and national data; critics question the influence of one funder over global health numbers.', 'Use for comparisons; check whether a country actually had measured data.'],
    ['ethnologue', 'Ethnologue (SIL International)', /ethnologue/i, 'Religious nonprofit', 'Published by SIL International, an evangelical Christian organization whose original mission is Bible translation.', 'Knowing every language helps translation and missionary work; it also sells subscriptions.', 'The most complete catalog of the world’s languages and speaker counts.', 'Some Indigenous groups and scholars have criticized missionary goals; speaker counts mix many sources and are revised often.', 'Very useful; be aware of its origins.'],
    ['ncdrisc', 'NCD-RisC', /ncd-?risc/i, 'Academic consortium', 'Network of health scientists led from Imperial College London, funded by research charities such as the Wellcome Trust.', 'Academic health research.', 'Height, weight and blood pressure trends for every country.', 'Modeled where measurements are missing.', 'Good for long-run nutrition trends.'],
    ['statemedia', 'State media (Xinhua, RT, CGTN, KCNA, etc.)', /Xinhua|CGTN|\bRT\b|KCNA|People’s Daily|Global Times/, 'Government-owned media', 'Owned and directed by governments (China, Russia, North Korea and others).', 'Advance the government’s narrative at home and abroad.', 'What a government wants you to believe; sometimes the only source inside closed countries.', 'Censorship and propaganda by design.', 'Treat as evidence of official positions, not of facts.'],
    ['corpmedia', 'Big news companies (Fox, CNN, NYT, WSJ, BBC…)', /Fox News|\bCNN\b|New York Times|\bNYT\b|Wall Street Journal|\bBBC\b/, 'Commercial or public media', 'Fox News and the Wall Street Journal are controlled by the Murdoch family; the New York Times by the Sulzberger family (public company); CNN by a large corporate parent; the BBC is funded by a UK license fee.', 'Commercial outlets need audiences and advertisers; partisan audiences reward partisan framing.', 'Reporting, investigations, interviews.', 'Each is accused of bias by the other side; ownership and advertisers shape what gets covered.', 'Read the same story in outlets with different audiences.'],
    ['primary', 'Primary documents (laws, censuses, court records)', /Census|Constitution|[Cc]ourt|records|ballot results|Nuremberg|declassified/, 'Original records', 'Created by governments, courts and officials at the time.', 'They record what the authorities of the day wanted recorded; censuses could undercount enslaved, colonized or nomadic people; court records reflect the law of their time.', 'The rawest evidence: exact legal wording, official counts, testimony under oath.', 'Not neutral: they show power’s view. Declassified documents arrive decades late and are often redacted.', 'Read the original wording yourself, then read historians who compare it with other evidence.'],
    ['inquiries', 'Official inquiries and commissions', /Inquiry|Commission|Survey Group|Lytton|Chilcot/, 'Government or international investigations', 'Set up by governments or international bodies (e.g. the UK Chilcot Inquiry, the US-led Iraq Survey Group, the League of Nations Lytton Commission).', 'Can clear or blame the people who appointed them; their mandates limit what they may examine.', 'Access to classified documents and witnesses under oath.', 'Accused of whitewashing (by critics of governments) or of political attacks (by governments’ allies); often published years after events.', 'Check the mandate, who appointed the members, and what was left out of scope.'],
    ['iom', 'International Organization for Migration (IOM)', /\bIOM\b|International Organization for Migration/, 'Intergovernmental (migration)', 'UN-related agency funded mostly by voluntary, project-based contributions from governments (the US and EU have been the largest).', 'Runs migration programs for governments, including some return programs critics say serve deterrence.', 'Migration and trafficking data; co-author of the modern slavery estimates.', 'Human rights groups criticize its role in returns from Libya and elsewhere; it depends on donor governments.', 'Good data on migration flows; note whose programs it runs.'],
    ['eurostat', 'Eurostat', /Eurostat/, 'EU statistics agency', 'Statistical office of the European Union, funded by the EU budget.', 'Comparable data across EU countries; its rules on deficits shape fiscal politics.', 'Economic and social statistics for Europe.', 'Relies on national statistics offices, as the Greek case showed.', 'Reliable for EU comparisons.'],
    ['journalism', 'News investigations (AP, Reuters, CNN and others)', /\bAP\b|Reuters|news reports|journalists/, 'News media', 'Commercial or nonprofit news organizations funded by subscriptions, advertising, or (for AP and Reuters) selling news to other outlets.', 'Scoops build reputation and audience; outlets also have owners and audiences with political leanings.', 'On-the-ground reporting that often exposes abuses first (e.g. AP’s 2015 seafood slavery investigation, which won a Pulitzer).', 'Speed can bring errors; coverage follows what audiences click; access journalism can soften reporting on the powerful.', 'Look for documents, named sources and follow-ups from other outlets.'],
    ['scholars', 'Individual historians and authors', /Hochschild|Blackmon|Hickel|Pritchett|Gallagher|Pinker|Roser|Rosling|historians/, 'Scholars and authors', 'Universities, publishers and book sales; some receive grants from foundations.', 'Reputation, book sales, academic careers, and sometimes a political or moral argument they want to win.', 'Deep research and synthesis.', 'Every author has a thesis; critics with opposite theses exist for almost every major book.', 'Read at least one serious critic of any book that shapes your view.'],
    ['nbs', 'Official national statistics (governments)', /national bureau of statistics|official (statistics|results)|government data/i, 'Government statistics', 'Run by governments.', 'Governments benefit from good-looking numbers.', 'Often the only full count of a population.', 'Manipulation is documented: Soviet output figures, Greece’s hidden deficits (revealed 2009), Argentina’s understated inflation (2007–15), China’s inflated provincial GDP (a future premier called it “man-made” in 2007, per WikiLeaks).', 'Check whether independent statisticians, satellites (night lights) or surveys agree.'],
    ['nsarchive', 'National Security Archive (George Washington University)', /National Security Archive/, 'Nonprofit archive of declassified documents', 'Founded in 1985 by journalists and scholars and based at George Washington University. Funded by private foundations and donors; it says it takes no government money. Files Freedom of Information requests and lawsuits to force releases.', 'Its mission is government openness, and its reputation rests on exposing what officials hid.', 'Tens of thousands of declassified US (and some foreign) documents on the Cold War, nuclear policy, coups and intelligence, published with context.', 'Some conservatives see a tilt toward documents that embarrass the US government. A structural bias is unavoidable: the US has a freedom-of-information law and closed states do not, so US misdeeds are far better documented than Soviet or Chinese ones.', 'Read the original documents it posts, not only its summaries, and remember that a missing Soviet document is not evidence of Soviet innocence.'],
    ['wilson', 'Wilson Center, Cold War International History Project', /Wilson Center|Cold War International History/, 'Think tank (US government chartered)', 'Created by the US Congress in 1968 and partly funded by federal money, plus foundations and donors. In 2025 the administration ordered it cut to the legal minimum and most staff were put on leave (developing).', 'Supports research and policy dialogue in Washington.', 'Its Cold War project (since 1991) has translated thousands of documents from former Soviet-bloc, Chinese and other archives, such as the Soviet records on the start of the Korean War.', 'Depends on what foreign archives chose to release (many Russian archives closed again after the 1990s); translations and selection are its own; critics on all sides question the government link.', 'Very valuable for the communist side of the Cold War; ask which archives the documents came from and what remains closed.'],
    ['hoover', 'Hoover Institution (Stanford)', /Hoover Institution/, 'Think tank and archive', 'Founded in 1919 by Herbert Hoover at Stanford; funded by an endowment and largely conservative donors. Its fellows have included many former Republican officials.', 'Promotes free markets, limited government and a strong defense; its scholars often argue those positions.', 'One of the world’s great archives on war, revolution and communism, including large Soviet-era collections.', 'Critics, including some Stanford faculty, say its scholarship leans right; defenders point to its archives, open to researchers of any view.', 'Use the archive freely; read its fellows’ arguments as one side of a debate.'],
    ['rand', 'RAND Corporation', /\bRAND\b/, 'Research organization (mostly government-funded)', 'Founded in 1948 out of a US Air Force project; most of its money still comes from US government contracts, especially the Defense Department.', 'Its clients are mostly agencies that commission studies, so its agenda is shaped by what they ask for.', 'Rigorous studies on nuclear strategy, military planning and policy. Daniel Ellsberg, who leaked the Pentagon Papers, worked there.', 'Critics on the left say it served Cold War nuclear strategy and the Vietnam War; critics also note that client-funded research rarely asks questions clients don’t want asked.', 'Good methods, but always ask who commissioned the study.'],
    ['usbs', 'US Strategic Bombing Survey', /Strategic Bombing Survey/, 'Official US government study (1944–47)', 'Set up by the War Department; led by civilians (including Paul Nitze and economist John Kenneth Galbraith) with military staff.', 'The Army Air Forces wanted proof that bombing had been decisive, which helped the case for an independent Air Force (created in 1947).', 'Huge data on bombing’s effects on Germany and Japan, including interviews with Japanese and German officials.', 'Its Germany reports found bombing less decisive than airmen claimed; historians (Gian Gentile, Robert Newman) argue its conclusion that Japan would have surrendered by late 1945 without the atomic bombs was not well supported by its own interviews.', 'A primary source, but one with an institutional stake in what airpower achieved.'],
    ['venona', 'Venona decrypts', /Venona/, 'Decrypted Soviet intelligence cables', 'A US Army and later NSA codebreaking project (1943–80) that partly decrypted Soviet cables from the 1940s; about 3,000 messages were released in 1995.', 'The NSA released them under pressure for openness after the Cold War.', 'Hard evidence of Soviet espionage in the US and Britain in the 1940s.', 'Only fragments were decrypted and people appear under cover names, so some identifications (Alger Hiss is the famous case) are still debated; critics such as Victor Navasky argue some historians over-read them.', 'Strong on whether a network existed; weaker on any single person’s identity.'],
    ['mitrokhin', 'Mitrokhin Archive', /Mitrokhin/, 'Defector’s notes from KGB files', 'Notes copied by KGB archivist Vasili Mitrokhin, who defected to Britain in 1992; published with historian Christopher Andrew, later MI5’s authorized historian.', 'British intelligence controlled access to the material and benefited from its publication.', 'Detailed evidence of KGB operations worldwide.', 'They are handwritten notes, not original documents, and cannot be checked independently in full; some uses (an Italian parliamentary commission) became politicized.', 'Treat as strong but secondhand; prefer points confirmed by other archives.'],
    ['church', 'Church Committee (US Senate, 1975–76)', /Church Committee/, 'Congressional investigation', 'A Senate select committee led by Senator Frank Church (Democrat), created after Watergate and press reports of illegal CIA spying at home.', 'Congress wanted to reassert control over the intelligence agencies; Democrats gained politically from exposing abuses.', 'Documented CIA assassination plots, FBI campaigns against domestic groups (COINTELPRO), mail opening and secret funding programs; led to permanent intelligence oversight committees and the 1978 FISA law.', 'The Ford administration and later critics argued it damaged US intelligence and was politically motivated; agencies withheld material.', 'Very reliable on what it documented; it saw only what it could pry loose.'],
    ['sovarch', 'Soviet and Russian state archives', /Soviet archives|Russian archives|Soviet records|Soviet documents/, 'Government archives', 'Controlled by the Soviet and then Russian state. Many were opened in the early 1990s, partly for political reasons (Yeltsin released the Katyn order during his fight with the Communist Party), and many have been closed again since. The Memorial society, which documented Gulag victims, was dissolved by Russian courts in 2021–22.', 'Each Russian government decides what history to support; today’s state favors a heroic wartime story and restricts criticism of Soviet conduct in WWII.', 'They settled many questions: execution quotas, Gulag numbers, Katyn, the secret protocols, the origins of the Korean War.', 'Access is selective and political; documents can be released to win present-day arguments; some records were destroyed.', 'Archive documents are strong evidence; ask what is still closed and why something was released when it was.'],
    ['memoirs', 'Generals’ memoirs and official war histories', /memoir|official histor|Historical Division/i, 'Participants’ accounts and government histories', 'Written by commanders and politicians about their own decisions, or by official historians employed by governments and armed forces.', 'Defending reputations, careers, pensions and national or service pride.', 'Inside knowledge of decisions and events, often the first detailed accounts.', 'Historians have shown many were self-serving: German generals’ memoirs built the “clean Wehrmacht” myth; historians such as Tim Travers argued Britain’s WWI official history shielded senior commanders; Soviet official histories hid the 1939–41 pact and failures.', 'Use for what the author saw; check every claim that makes the author look good against documents from the time.'],
    ['propministries', 'Wartime propaganda agencies', /Wellington House|propaganda ministry|Office of War Information|Committee on Public Information/i, 'Government propaganda bodies', 'Britain’s War Propaganda Bureau (Wellington House) and the US Committee on Public Information in WWI; Goebbels’ ministry in Nazi Germany; the US Office of War Information and the Soviet information bureau in WWII.', 'Morale at home, hatred of the enemy, support from neutrals; truth was secondary by design.', 'Evidence of what governments wanted people to believe, and how.', 'Every one mixed truth, exaggeration and invention.', 'Never treat as evidence of facts; treat as evidence of intentions.'],
    ['hamburg', 'Hamburg Institute for Social Research', /Hamburg Institute/, 'Private research institute', 'Founded in 1984 and funded by Jan Philipp Reemtsma from his family’s tobacco fortune.', 'A mission to study violence and dictatorship; it organized the 1995 “Crimes of the Wehrmacht” exhibition.', 'Brought research on army crimes to the public.', 'Veterans, conservatives and the far right attacked it; historians found some photos were misattributed, so the exhibition was withdrawn in 1999 and revised; an expert commission upheld its core thesis.', 'A useful case of a source that made errors, corrected them, and was still right on the main point.'],
    ['pentagonpapers', 'The Pentagon Papers', /Pentagon Papers/, 'Leaked government study', 'A secret Defense Department history of US decision-making in Vietnam (1945–67), commissioned by Defense Secretary McNamara and leaked in 1971 by Daniel Ellsberg, a former RAND analyst.', 'Written for internal use, so officials had little reason to spin it for the public; Ellsberg leaked it to end the war.', 'Shows what officials believed privately versus what they said in public.', 'Covers only to 1967 and only Defense Department records; the Nixon administration fought publication in court and lost (1971).', 'One of the best sources on official deception, because it was never meant to be seen.'],
    ['crs', 'Congressional Research Service (CRS)', /\bCRS\b|Congressional Research Service/, 'Congress’s research arm', 'Part of the Library of Congress, funded by Congress and working only for members and committees. Its reports became officially public only in 2018.', 'Its job is to inform lawmakers of both parties, so it avoids recommendations.', 'Careful, sourced summaries of laws, budgets, alliances and foreign policy.', 'Critics say its caution can blur conclusions; it relies heavily on official US sources.', 'Very reliable for facts and legal background; look elsewhere for judgment.'],
    ['gao', 'Government Accountability Office (GAO)', /\bGAO\b|Government Accountability Office/, 'Congress’s auditor', 'An independent agency of Congress led by a Comptroller General appointed for 15 years.', 'Its reputation depends on independence; it has no power to force agencies to fix what it finds.', 'Audits of weapons costs (such as the F-35), the revolving door, and Pentagon finances.', 'Its warnings are often ignored; it can audit only what it is asked to or allowed to see.', 'Strong evidence on waste and cost; check whether its recommendations were adopted.'],
    ['pogo', 'Project On Government Oversight (POGO)', /\bPOGO\b|Project On Government Oversight/i, 'Watchdog nonprofit', 'Founded in 1981 to expose Pentagon waste; funded by foundations and individual donors.', 'Its mission and fundraising depend on finding waste and misconduct.', 'Investigations of the revolving door, contracting and weapons programs.', 'Defenders of the industry say it assumes the worst about contractors.', 'Good on documented cases; weigh its framing against industry and Pentagon responses.'],
    ['quincy', 'Quincy Institute for Responsible Statecraft', /Quincy Institute/, 'Think tank (restraint)', 'Founded in 2019 with money from both the Charles Koch Foundation and George Soros’s Open Society Foundations, plus other donors.', 'Advocates military restraint and diplomacy; its research supports cutting overseas commitments.', 'Data-heavy reports on Pentagon contracts and arms sales, often with academic partners.', 'Hawkish critics accuse it of being soft on Russia, China and Iran; it rejects that and says it is transparent about donors.', 'Use its numbers (usually from public data); read its conclusions as the restraint side of a debate.'],
    ['costsofwar', 'Costs of War project (Brown University)', /Costs of War/, 'University research project', 'Based at Brown University’s Watson Institute since 2010; funded by foundations; contributors are mostly academics critical of the post-9/11 wars.', 'Aims to show the full human and financial cost of the wars.', 'The most cited estimates of deaths and dollar costs of the war on terror.', 'Critics question its methods for indirect deaths and some cost projections (for example future veterans’ care).', 'Use direct-death counts with confidence; treat indirect estimates as ranges.'],
    ['csis', 'CSIS (Center for Strategic and International Studies)', /\bCSIS\b/, 'Think tank (establishment security)', 'Funded by corporations including major defense contractors, foreign governments, foundations and the US government; it lists donors by range.', 'Close to the national-security establishment of both parties; staff often move in and out of government.', 'Expert analysis of budgets, weapons, war games and Asia policy.', 'A 2016 New York Times investigation and other critics raised conflicts of interest when think tanks funded by industry or foreign governments recommend policies benefiting those donors.', 'Excellent technical work; ask who funds the program behind a given report.'],
    ['atlantic', 'Atlantic Council', /Atlantic Council/, 'Think tank (pro-NATO)', 'Funded by the US and foreign governments (including Gulf states), NATO bodies, defense contractors, corporations and foundations; donors listed by range.', 'Strongly supports NATO and US leadership in alliances.', 'Analysis and open-source investigations (its Digital Forensic Research Lab tracks disinformation).', 'Critics on the left and right say foreign-government and industry money shapes its positions; its defenders cite donor disclosure.', 'Useful, but read it as an advocate for the alliance system.'],
    ['cfr', 'Council on Foreign Relations (CFR)', /\bCFR\b|Council on Foreign Relations/, 'Think tank and membership organization', 'Founded in 1921; funded by members, corporate members and foundations; publishes Foreign Affairs.', 'The voice of the bipartisan foreign-policy establishment.', 'Explainers and conflict trackers, with experts from many views.', 'Critics on the left and populist right see it as an establishment club; conspiracy theories about it controlling the world are unfounded.', 'Good for mainstream establishment views and quick background.'],
    ['wbw', 'World BEYOND War and David Vine’s base counts', /World BEYOND War|David Vine/, 'Anti-war advocacy group and allied scholar', 'A nonprofit campaigning to abolish war, funded by donors; anthropologist David Vine (American University) compiles its lists of US bases.', 'Its goal is closing bases, so larger counts support its case.', 'The most detailed public lists of US military sites abroad.', 'Counts depend on definitions: its ~750 figure includes small facilities; the Pentagon’s own lists show far fewer major bases.', 'Use as one end of a range, alongside official counts.'],
    ['keia', 'Korea Economic Institute of America (KEIA)', /\bKEIA\b|Korea Economic Institute/, 'Think tank (Korea)', 'Based in Washington and funded mainly by a South Korean government-affiliated research institute.', 'Promotes understanding of Korea and the alliance in the US.', 'Detailed, accessible analysis of US–Korea trade and security.', 'Its funding means it is unlikely to be harshly critical of Seoul’s official positions.', 'Good for facts and Seoul’s perspective; compare with independent Korean and US sources.'],
    ['koreanmedia', 'South Korean news media', /Korea Times|Korea Herald|Yonhap|Kyunghyang|Hankyoreh|Chosun/, 'News media', 'Yonhap is a publicly funded news agency; the Korea Times and Korea Herald are English-language dailies owned by Korean business groups; major Korean papers have clear leanings (Chosun and JoongAng conservative; Hankyoreh and Kyunghyang progressive).', 'Commercial and political audiences at home.', 'Korean perspectives and details US media miss.', 'Partisan framing on alliance and North Korea issues is common on both sides.', 'Compare a conservative and a progressive outlet on the same story.'],
    ['usgov', 'US government statements (White House, Pentagon, ODNI)', /\bDoD\b|\bODNI\b|White House|US government|Commerce Department|Federal Reserve|US Treasury|DNI/, 'Official government sources', 'Paid by taxpayers and run by the administration in power.', 'Every administration presents its own policies favorably; agencies protect their budgets and reputations.', 'Official figures (budgets, troop numbers, strategy documents) that often exist nowhere else.', 'Historically, officials have misled the public on war and surveillance (see Pentagon Papers, Gulf of Tonkin, Clapper 2013).', 'Use for official numbers and stated intentions; verify claims about success or threats independently.'],
    ['tradepress', 'Defense trade press (Breaking Defense, Defense News)', /Breaking Defense|Defense News/, 'Specialist news media', 'Commercial publications funded largely by advertising and events, much of it from defense companies.', 'Their audience is the defense industry and the Pentagon.', 'Fast, detailed reporting on budgets, contracts and programs.', 'Critics say industry advertising makes them gentle on contractors; they do report failures such as audits.', 'Reliable for facts and numbers; read their framing as an insider view.'],
    ['contractdata', 'Federal contract data (FPDS, USAspending, Bloomberg Government, GovTribe)', /Bloomberg Government|federal contract data|GovTribe|USAspending/, 'Government data and commercial analysis', 'The government publishes contract records; companies like Bloomberg Government and GovTribe sell analysis of them.', 'Commercial services sell to contractors seeking business.', 'Who got which contracts and how much.', 'Classified contracts are missing, and totals differ by method (for example, whether cancelled amounts are subtracted).', 'Good for comparisons; expect different totals from different counters.'],
    ['politicians', 'Reports by members of Congress', /Warren report|Sen\. Warren|senator’s report/, 'Political reports', 'Written by a member’s staff with public money.', 'Serve the member’s agenda (Senator Warren, for example, campaigns against defense-industry influence).', 'Can compile hard-to-find data on lobbying and hiring.', 'Selective by design; opponents rarely get to respond in them.', 'Check the underlying data and look for a response from the other side.'],
  ];
  Lab.SOURCES = S.map(([id, n, re, type, who, gain, good, crit, how]) => ({ id, n, re, type, who, gain, good, crit, how }));
  Lab.SOURCE_RULES = ['Who pays them? (owners, donors, governments, advertisers)', 'What do they gain if you believe this? (money, influence, mission, reputation)', 'Who do they work with, and who appoints their leaders?', 'What is their track record? Have they corrected mistakes?', 'Who criticizes them, and what do the critics gain?', 'Can you see the raw data and methods, or only the conclusion?', 'Do independent sources with different funders find the same thing?'];
  Lab.sourceMatch = (text) => Lab.SOURCES.filter((s) => s.re.test(text || ''));
  Lab.sourceCard = (s, compact) => h('div', { class: 'card', style: { boxShadow: 'none', marginBottom: '8px' } }, h('div', { class: 'row' }, h('b', null, s.n), h('span', { class: 'tag', style: { '--c': '#475569' } }, s.type)),
    ...[['💰 Who runs and pays them', s.who], ['🎯 What they want or gain', s.gain], ['✅ What they are good for', s.good], ['⚠️ Criticisms (and from whom)', s.crit], ['🧭 How to read them', s.how]].map(([t, d]) => h('div', { style: { marginTop: '6px' } }, h('div', { class: 'tiny', style: { fontWeight: 700 } }, t), h('div', { class: 'small' }, d))),
    h('button', { class: 'btn sm', style: { marginTop: '8px' }, onclick: () => Lab.ask(`Investigate ${s.n} as a source for me: who funds and controls it today, what it gains from its claims, who it works with, its track record and corrections, its strongest critics and what those critics gain. Cite sources from different sides and tell me what you are unsure about.`, s.n) }, '✦ Investigate further with the tutor'));
  Lab.sourcePanel = (list) => { const box = h('div', { class: 'card', style: { boxShadow: 'none', background: 'var(--card2)', marginTop: '6px' } }, h('div', { class: 'small', style: { fontWeight: 700, marginBottom: '6px' } }, 'Who is telling you this?'), ...list.map((s) => Lab.sourceCard(s)), h('div', { class: 'tiny muted' }, 'Questions to ask of any source: ' + Lab.SOURCE_RULES.join(' · '))); return box; };
  const base = Lab.source;
  Lab.source = (html) => { const el = base(html); const m = Lab.sourceMatch(String(html).replace(/<[^>]+>/g, ' ')); if (m.length) { let open = null; el.append(' ', h('a', { href: '#', class: 'tiny', style: { fontWeight: 600 }, onclick: (e) => { e.preventDefault(); if (open) { open.remove(); open = null; } else { open = Lab.sourcePanel(m); el.append(open); } } }, `🔍 Who are they? (${m.length})`)); } return el; };

  Lab.routes.whois = function (app) {
    document.documentElement.style.setProperty('--accent', '#475569'); Lab.setContext('Who is telling me this? Source dossiers');
    let q = ''; const list = h('div', { class: 'grid g2', style: { alignItems: 'start' } });
    const draw = () => { list.innerHTML = ''; Lab.SOURCES.filter((s) => !q || (s.n + s.type + s.who + s.crit).toLowerCase().includes(q)).forEach((s) => list.append(Lab.sourceCard(s))); };
    app.append(h('section', { class: 'hero' }, h('a', { class: 'crumb', href: '#home' }, '← Home'), h('div', { class: 'emoji', style: { marginTop: '10px' } }, '🔍'), h('h1', null, 'Who is telling me this?'), h('p', null, 'Every number in this Lab comes from someone. Here is who they are, who pays them, what they gain, and who criticizes them. No source is neutral; some are more transparent and more often right than others. The goal is not to distrust everything, but to know what to check.')),
      h('div', { class: 'card' }, h('h3', { style: { marginTop: 0 } }, 'Seven questions for any source'), h('ol', { class: 'small', style: { lineHeight: 1.8 } }, Lab.SOURCE_RULES.map((r) => h('li', null, r))), h('p', { class: 'small muted' }, 'Apply the same questions to critics: a think tank attacking a study also has funders and goals. Agreement between sources with opposite incentives is the strongest evidence you can get.'),
        h('input', { type: 'text', placeholder: 'Search sources…', style: { minWidth: '260px' }, oninput: (e) => { q = e.target.value.toLowerCase(); draw(); } }), (() => { const inv = h('input', { type: 'text', placeholder: 'Any outlet, think tank, author…', style: { minWidth: '220px', marginLeft: '8px' } }); return h('span', null, inv, h('button', { class: 'btn sm primary', style: { marginLeft: '6px' }, onclick: () => { const n = inv.value.trim(); if (n) Lab.ask(`Investigate "${n}" as a source: who owns or funds it, what it gains from what it publishes, who it works with, its political leanings, track record and corrections, and its strongest critics (and what they gain). Be specific and cite sources from different sides.`, n); } }, '✦ Investigate it')); })()),
      list);
    draw();
  };
})();
